effect.shader:
// Fisheye / Anti‑Fisheye
// Ported from the Shadertoy snippet provided by the user and adapted for Alight Motion
// Inspired by: https://stackoverflow.com/questions/6030814

// Notes:
// - power > 0 : fisheye (barrel)
// - power < 0 : anti‑fisheye (pincushion)
// - aspectMode!=0 applies aspect correction so the effect remains circular on non‑square frames

void main(){
  vec2 uv = acScreenNorm;            // 0..1
  vec2 uvWork = uv;                  // working UVs (may be aspect-adjusted)

  float prop = acScreenSize.x / acScreenSize.y;  // aspect ratio (width/height)

  // Aspect-corrected center
  vec2 m = vec2(centerX, (aspectMode != 0) ? (centerY / prop) : centerY);

  // Aspect-corrected working coordinates for circular behavior
  if(aspectMode != 0){
    uvWork = vec2(uv.x, uv.y / prop);
  }

  vec2 d = uvWork - m;              // vector from center
  float r = length(d);              // distance from center

  // Map UI power [-1..1] to a usable curvature scale (radians-like)
  // Using PI scaling provides a useful range similar to the original mouse mapping
  float k = power * 3.14159265;

  // Compute bind radius according to original logic
  float bind;
  if(k > 0.0){
    bind = length(m);                 // stick to corners for fisheye
  } else if(k < 0.0){
    bind = (prop < 1.0) ? m.x : m.y; // borders when anti‑fisheye
  } else {
    bind = 1.0; // not used when k == 0
  }

  vec2 uv2;
  if(k > 0.0){
    // fisheye
    uv2 = m + normalize(d) * tan(r * k) * bind / tan(bind * k);
  } else if(k < 0.0){
    // anti‑fisheye (scaled by 10 like the reference)
    float kk = -k * 10.0;
    uv2 = m + normalize(d) * atan(r * kk) * bind / atan(kk * bind);
  } else {
    uv2 = uvWork; // no effect
  }

  // Undo aspect correction for sampling
  if(aspectMode != 0){
    uv2 = vec2(uv2.x, uv2.y * prop);
  }

  // Sample with clamping at edges
  vec4 src = texture2DCv(inputImg.texture, clamp(uv2, 0.0, 1.0));

  // Preserve original alpha and allow overall alpha control
  float a = src.a * alpha;
  gl_FragColor = vec4(src.rgb, 1.0) * a;
}
